import { Check, CircleHelp, Hourglass, X, type LucideIcon } from 'lucide-react-native';

import { Badge, type BadgeProps } from '@/components/ui/badge';
import { Icon } from '@/components/ui/icon';
import { Text } from '@/components/ui/text';

// TODO: use the type generated by pocketbase-typegen once the answers collection exists.
export type AnswerStatus = 'present' | 'absent' | 'waiting_list' | 'no_answer';

const STATUSES: Record<
  AnswerStatus,
  { label: string; icon: LucideIcon; variant: NonNullable<BadgeProps['variant']> }
> = {
  present: { label: 'Présent', icon: Check, variant: 'success' },
  absent: { label: 'Absent', icon: X, variant: 'danger' },
  waiting_list: { label: "Liste d'attente", icon: Hourglass, variant: 'warning' },
  no_answer: { label: 'Sans réponse', icon: CircleHelp, variant: 'neutral' },
};

type StatusBadgeProps = Omit<BadgeProps, 'variant' | 'children'> & { status: AnswerStatus };

/** Answer status of a member: always an icon and a label, never a color alone. */
export function StatusBadge({ status, ...props }: StatusBadgeProps) {
  const { label, icon, variant } = STATUSES[status];
  return (
    <Badge variant={variant} {...props}>
      <Icon as={icon} testID="status-badge-icon" aria-hidden />
      <Text>{label}</Text>
    </Badge>
  );
}
